jsxGraph.script:
board.suspendUpdate();
// Draw x-axis line
board.create('segment', [[10,0], [20,0]], {strokeColor:'#64748b', strokeWidth: 1.5, fixed: true});

// Draw Normal Distribution Curve
var mean = 15;
var sd = 1.5;
var normPDF = function(x) {
  return (1 / (sd * Math.sqrt(2 * Math.PI))) * Math.exp(-0.5 * Math.pow((x - mean) / sd, 2));
};
board.create('functiongraph', [normPDF, 10, 20], {strokeColor:'#2563eb', strokeWidth: 3, fixed: true});

// Shading the disqualified region (x > 16.5)
board.create('integral', [[16.5, 20], board.objectsList[board.objectsList.length-1]], {
  fillColor: '#ef4444',
  fillOpacity: 0.3,
  strokeColor: 'none',
  label: {visible: false}
});

// Mark mean (15)
board.create('segment', [[15, 0], [15, normPDF(15)]], {strokeColor:'#475569', strokeWidth: 1, dash: 2, fixed: true});
board.create('text', [14.8, -0.02, '15'], {fontSize: 12, fixed: true, fontStyle: 'bold'});

// Mark standard deviations
board.create('segment', [[13.5, 0], [13.5, normPDF(13.5)]], {strokeColor:'#94a3b8', strokeWidth: 1, dash: 2, fixed: true});
board.create('text', [13.2, -0.02, '13.5'], {fontSize: 11, fixed: true});

board.create('segment', [[16.5, 0], [16.5, normPDF(16.5)]], {strokeColor:'#ef4444', strokeWidth: 1.5, dash: 2, fixed: true});
board.create('text', [16.3, -0.02, '16.5'], {fontSize: 11, fixed: true, fontStyle: 'bold', color: '#ef4444'});

// Labels
board.create('text', [17.0, 0.08, 'Disqualified\n(16%)'], {fontSize: 11, color: '#b91c1c', fixed: true});

board.unsuspendUpdate();

board.suspendUpdate();
